import{_ as s,o as t,c as n,a3 as i}from"./chunks/framework.MGD2uYU7.js";const f=JSON.parse('{"title":"SC-49 — Audit log (admin)","description":"","frontmatter":{"title":"SC-49 — Audit log (admin)"},"headers":[],"relativePath":"wireframes/admin/sc-49-audit-log.md","filePath":"wireframes/admin/sc-49-audit-log.md","lastUpdated":null}'),l={name:"wireframes/admin/sc-49-audit-log.md"};function d(c,a,e,p,o,r){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="sc-49-—-audit-log-admin" tabindex="-1">SC-49 — Audit log (admin) <a class="header-anchor" href="#sc-49-—-audit-log-admin" aria-label="Permalink to &quot;SC-49 — Audit log (admin)&quot;">​</a></h1><p><span class="wf-badge danger">ADMIN</span> <span class="wf-badge info">Route: /admin/audit</span> <span class="wf-badge muted">Nguồn: docs/05 §3 · docs/06 endpoint 62 · docs/07 §2.17 · docs/08 BR-ADM-01/02 · docs/02 FR-ADM-04 + NFR-S-06</span></p><p><strong>Ai xem màn này</strong>: ADMIN (vận hành + người điều tra sự cố), CS lead khi xử lý khiếu nại (&quot;ai đã duyệt/hủy/xác nhận cái này, lúc nào, vì sao&quot;). <strong>Mục đích</strong>: tra cứu <strong>toàn bộ dấu vết mutation của hệ thống</strong> — actor, action, entity, diff before/after (đã redact PII), ip, traceId. <strong>VIEW-ONLY tuyệt đối: màn này không có bất kỳ nút tạo/sửa/xóa nào ở đâu</strong> — chỉ lọc, xem, xuất CSV. <strong>Ví dụ số dùng trong bản vẽ</strong>: các log sinh ra từ chính flow SC-44..48 (PAYMENT_CONFIRM_MANUAL của pay_01J9ZM4T2W, AUCTION_EXTEND #3 của auc_01J9X3K8M2, USER_SUSPEND le.van.c, USER_RESET_PASSWORD của Nguyễn Văn A).</p><div class="wf"><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);"><b>Audit log là bất biến — không có thao tác sửa/xóa.</b> DB chỉ cấp quyền INSERT/SELECT (không UPDATE/DELETE), không tồn tại API chỉnh sửa; append-only ở tầng schema. Nếu designer/dev thấy bất kỳ nút mutation nào trên màn này — đó là bug. <span class="wf-callout danger">1</span></div></div><h2 id="_1-desktop-—-bo-loc-bang-audit" tabindex="-1">1. Desktop — bộ lọc + bảng audit <a class="header-anchor" href="#_1-desktop-—-bo-loc-bang-audit" aria-label="Permalink to &quot;1. Desktop — bộ lọc + bảng audit&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/admin/audit?action=&amp;actor=&amp;entity=&amp;from=&amp;to=</span></div><div class="wf-body"><div class="wf-row" style="align-items:stretch;gap:0;"><div class="wf-admin-rail"><span class="brand">AnPhuc Admin</span><span class="item">Dashboard</span><span class="item">KYC</span><span class="item">Tin</span><span class="item">Dự án</span><span class="item">Đấu giá</span><span class="item">Thanh toán</span><span class="item">Người dùng</span><span class="item active">Audit</span></div><div class="wf-grow wf-col" style="padding:16px;min-width:0;gap:12px;"><div class="wf-row between middle"><span class="wf-title lg">Audit log <span class="wf-badge danger">VIEW-ONLY</span> <span class="wf-callout">2</span></span><span class="wf-btn sm ghost">Xuất CSV (theo filter) <span class="wf-callout">7</span></span></div><div class="wf-row middle wrap" style="gap:8px;"><div class="wf-input" style="min-width:190px;">Actor: Tất cả (admin.tran ▾)<span class="caret">▾</span></div><div class="wf-input" style="min-width:210px;">Action: Tất cả<span class="caret">▾</span></div><div class="wf-input" style="min-width:180px;">Entity: Tất cả<span class="caret">▾</span></div><div class="wf-input" style="min-width:200px;">Entity ID: auc_ / pay_ / usr_ …<span class="caret">✎</span></div><div class="wf-input" style="min-width:130px;">Từ 01/10/2026<span class="caret">🗓</span></div><div class="wf-input" style="min-width:130px;">Đến 10/10/2026<span class="caret">🗓</span></div><div class="wf-input" style="min-width:170px;">traceId: khớp error user báo<span class="caret">✎</span></div><span class="wf-btn sm primary">Áp dụng</span><span class="wf-btn sm ghost">Xóa lọc</span></div><table class="wf-table"><thead><tr><th>Thời gian (GMT+7)</th><th>Actor</th><th>Action</th><th>Entity</th><th>Diff tóm tắt</th><th>traceId</th><th></th></tr></thead><tbody><tr><td>10/10/2026 11:02:44</td><td>admin.tran@anphuc.vn<br><span class="wf-small">ip 113.xx.xx.21</span></td><td><span class="wf-badge ok">PAYMENT_CONFIRM_MANUAL</span></td><td>payment<br><span class="wf-trace">pay_01J9ZM4T2W</span></td><td><span class="wf-small">state: PROCESSING → SUCCESS <span class="wf-callout">3</span></span></td><td><span class="wf-trace">4f2a9c1e</span></td><td><span class="wf-btn sm">Xem diff</span></td></tr><tr><td>10/10/2026 10:58:03</td><td><b>system</b><br><span class="wf-small">job anti-snipe (actor NULL)</span></td><td><span class="wf-badge warn">AUCTION_EXTEND</span></td><td>auction<br><span class="wf-trace">auc_01J9X3K8M2</span></td><td><span class="wf-small">effective_end_at: 14:45:07 → 14:46:07 (+60s, lần #3) <span class="wf-callout">4</span></span></td><td><span class="wf-trace">b07e2c44</span></td><td><span class="wf-btn sm">Xem diff</span></td></tr><tr><td>10/10/2026 09:12:31</td><td>admin.linh@anphuc.vn<br><span class="wf-small">ip 113.xx.xx.8</span></td><td><span class="wf-badge info">PROJECT_UPDATE</span></td><td>housing_project<br><span class="wf-trace">prj_01JZK3M9W2</span></td><td><span class="wf-small">completionYear: 2026 → 2027 (PATCH không đổi field nào → không ghi log)</span></td><td><span class="wf-trace">8d11f6a0</span></td><td><span class="wf-btn sm">Xem diff</span></td></tr><tr><td>08/10/2026 11:15:39</td><td>admin.tran@anphuc.vn<br><span class="wf-small">ip 113.xx.xx.21</span></td><td><span class="wf-badge danger">USER_RESET_PASSWORD</span></td><td>user<br><span class="wf-trace">usr_01J8K2M9Q4</span></td><td><span class="wf-small">{reason: &quot;YC-88 CS Nguyễn…&quot;, revokedRefreshCount: 2} — <b>không</b> chứa mật khẩu tạm <span class="wf-callout">5</span></span></td><td><span class="wf-trace">c53ab902</span></td><td><span class="wf-btn sm">Xem diff</span></td></tr><tr><td>07/10/2026 16:20:11</td><td>admin.tran@anphuc.vn<br><span class="wf-small">ip 113.xx.xx.21</span></td><td><span class="wf-badge danger">USER_SUSPEND</span></td><td>user<br><span class="wf-trace">usr_01J8C4E7G2</span></td><td><span class="wf-small">status: ACTIVE → SUSPENDED · reason: &quot;forfeit DGA-2025-0118 — ticket CS-102&quot;</span></td><td><span class="wf-trace">e19c0d77</span></td><td><span class="wf-btn sm">Xem diff</span></td></tr><tr><td>07/10/2026 10:05:00</td><td>admin.linh@anphuc.vn<br><span class="wf-small">ip 113.xx.xx.8</span></td><td><span class="wf-badge warn">LISTING_REJECT</span></td><td>housing_listing<br><span class="wf-trace">lst_01JZK3M9W2Q8</span></td><td><span class="wf-small">state: IN_REVIEW → REJECTED · reason: &quot;Ảnh số 3 không thuộc căn đăng bán…&quot;</span></td><td><span class="wf-trace">a44de150</span></td><td><span class="wf-btn sm">Xem diff</span></td></tr><tr><td>07/10/2026 02:00:05</td><td><b>system</b><br><span class="wf-small">job payBy 24h</span></td><td><span class="wf-badge danger">ORDER_FORFEIT</span></td><td>settlement_order<br><span class="wf-trace">ord_01J9B7T3K5</span></td><td><span class="wf-small">state: PENDING → EXPIRED · deposit 90.000.000 ₫ → FORFEITED · privilege → SUSPENDED <span class="wf-callout">6</span></span></td><td><span class="wf-trace">f70b3a19</span></td><td><span class="wf-btn sm">Xem diff</span></td></tr></tbody></table><div class="wf-row between middle"><span class="wf-small">Trang 1/207 · 4.132 log · sort cố định: created_at giảm dần (không re-sort — thứ tự thời gian là bất khả xâm phạm)</span><div class="wf-pagination" style="margin-top:0;"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">3</span><span class="pg">…</span><span class="pg">207</span><span class="pg">›</span></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/08 BR-ADM-01/02 · docs/07 §2.17 · docs/02 FR-ADM-04 + NFR-S-06)</div><ol><li><span class="num">1</span><span><b>Append-only ở mọi tầng</b>: DB grant chỉ INSERT/SELECT, không API UPDATE/DELETE, không UI mutation. Note đỏ đầu trang là lời tuyên bố design — mọi frame Figma của màn này không được chứa icon bút/thùng rác. <span class="ref">BR-ADM-02</span></span></li><li><span class="num">2</span><span>Badge &quot;VIEW-ONLY&quot; cạnh title để admin mới không đi tìm nút sửa. Nguồn dữ liệu <code>GET /admin/audit-logs</code> — mọi mutation ADMIN + mọi extend anti-snipe + mọi manual confirm đều có mặt ở đây (100% coverage). <span class="ref">FR-ADM-04</span> <span class="ref">NFR-S-06</span> <span class="ref">endpoint 62</span></span></li><li><span class="num">3</span><span><b>Bộ lọc</b>: actor (admin/system) · action (enum AuditAction — KYC_APPROVE, LISTING_REJECT, AUCTION_PUBLISH, AUCTION_EXTEND, PAYMENT_CONFIRM_MANUAL, USER_SUSPEND, ORDER_FORFEIT, USER_RESET_PASSWORD, PROJECT_CREATE/UPDATE…) · entity type + entity id · date range · traceId (khớp traceId trong hộp lỗi user chụp gửi CS — con đường điều tra nhanh nhất). <span class="ref">docs/07 §2.17</span></span></li><li><span class="num">4</span><span><b>actor NULL = system</b> (job): hiển thị &quot;system&quot; + tên job — phân biệt rõ người làm vs máy làm. AUCTION_EXTEND system + tần suất bất thường = dữ liệu điều tra thông đồng. <span class="ref">docs/07 §2.17</span></span></li><li><span class="num">5</span><span><b>Diff đã redact PII</b> trước khi ghi (NFR-S-05): CCCD mask, USER_RESET_PASSWORD chỉ lưu {reason, revokedRefreshCount} — không bao giờ có mật khẩu tạm; audit hiển thị gì CS thấy nấy, không có &quot;chế độ xem đầy đủ&quot;. <span class="ref">BR-ADM-04</span> <span class="ref">NFR-S-05</span></span></li><li><span class="num">6</span><span>Diff tóm tắt 1 dòng ngay trên bảng (field: before → after) để quét nhanh; chi tiết JSON đầy đủ ở drawer (mục 2). Entity id click được → deep-link màn liên quan ở chế độ read-only (pay_ → SC-47 drawer, auc_ → SC-46, usr_ → SC-48). <span class="ref">docs/05 §3</span></span></li><li><span class="num">7</span><span><b>Xuất CSV theo filter hiện hành</b> (endpoint export riêng, giới hạn 50k dòng — quá thì báo &quot;thu hẹp khoảng ngày&quot;); chính hành động export cũng là một thao tác đọc nhạy cảm: ghi audit <code>AUDIT_EXPORT</code> (ai xuất, filter gì, lúc nào). <span class="ref">FR-STAT-02</span></span></li></ol></div><h2 id="_2-drawer-chi-tiet-log-—-diff-json-before-after-read-only" tabindex="-1">2. Drawer chi tiết log — diff JSON before/after (read-only) <a class="header-anchor" href="#_2-drawer-chi-tiet-log-—-diff-json-before-after-read-only" aria-label="Permalink to &quot;2. Drawer chi tiết log — diff JSON before/after (read-only)&quot;">​</a></h2><div class="wf"><div class="wf-row" style="align-items:flex-start;gap:0;"><div class="wf-grow" style="opacity:0.35;padding:16px;"><table class="wf-table"><thead><tr><th>Thời gian</th><th>Actor</th><th>Action</th><th>Entity</th></tr></thead><tbody><tr><td>10/10/2026 11:02:44</td><td>admin.tran</td><td><span class="wf-badge ok">PAYMENT_CONFIRM_MANUAL</span></td><td><span class="wf-trace">pay_01J9ZM4T2W</span></td></tr><tr><td>10/10/2026 10:58:03</td><td>system</td><td><span class="wf-badge warn">AUCTION_EXTEND</span></td><td><span class="wf-trace">auc_01J9X3K8M2</span></td></tr></tbody></table><span class="wf-small">(bảng phía sau làm mờ — drawer trượt phải, đóng bằng ESC/nút ×)</span></div><div class="wf-drawer wf-col" style="gap:10px;width:420px;"><div class="wf-row between middle"><span class="wf-title">Log log_01J9ZP3K8 <span class="wf-badge danger">READ-ONLY</span></span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">ACTION</span><span class="wf-strong">PAYMENT_CONFIRM_MANUAL</span><span class="wf-small wf-muted" style="margin-top:4px;">ACTOR · THỜI GIAN</span><span class="wf-small">admin.tran@anphuc.vn (<span class="wf-trace">usr_01J7ADM2N9</span>) · 10/10/2026 11:02:44 (GMT+7) · ip 113.xx.xx.21</span><span class="wf-small wf-muted" style="margin-top:4px;">ENTITY</span><span class="wf-small">payment <span class="wf-trace">pay_01J9ZM4T2W</span> <span class="wf-accent">→ mở tại SC-47 (read-only)</span></span><span class="wf-small wf-muted" style="margin-top:4px;">TRACE</span><span class="wf-trace">traceId: 4f2a9c1e-77b0-4d3a — khớp log ứng dụng + hộp lỗi user (nếu có)</span></div><div class="wf-col" style="gap:4px;border-top:2px solid var(--wf-line-strong);padding-top:8px;"><span class="wf-small wf-muted">DIFF (JSON, redact PII — ghi 1 lần lúc hành động xảy ra) <span class="wf-callout">8</span></span><div class="wf-card flat"><div class="pad"><span class="wf-trace">{</span><br><span class="wf-trace">  &quot;before&quot;: { &quot;state&quot;: &quot;PROCESSING&quot; },</span><br><span class="wf-trace">  &quot;after&quot;: {</span><br><span class="wf-trace">    &quot;state&quot;: &quot;SUCCESS&quot;,</span><br><span class="wf-trace">    &quot;confirmedBy&quot;: &quot;usr_01J7ADM2N9&quot;,</span><br><span class="wf-trace">    &quot;confirmedAt&quot;: &quot;2026-10-10T04:02:44.118Z&quot;</span><br><span class="wf-trace">  },</span><br><span class="wf-trace">  &quot;note&quot;: &quot;So phu VCB 10/10 GD 88214077, tien vao 11:05&quot;</span><br><span class="wf-trace">}</span></div></div><span class="wf-small wf-muted">Timestamp trong diff là UTC (ISO-8601) — UI hiển thị GMT+7; không format lại giá trị gốc. <span class="wf-callout">9</span></span></div><div class="wf-col" style="gap:6px;border-top:1px solid var(--wf-line);padding-top:8px;"><span class="wf-btn ghost block">Sao chép traceId (gửi kỹ thuật khi điều tra)</span><span class="wf-small wf-center wf-muted">Không có nút sửa/xóa/chỉnh diff — ở bất kỳ đâu. Muốn &quot;đính chính&quot;? Tạo một nghiệp vụ mới, log mới sẽ tự ghi.</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">8</span><span>Diff render <b>nguyên văn JSON đã lưu</b> (monospace, không beautify thêm/bớt field) — giá trị pháp lý của audit nằm ở tính nguyên bản. before/after theo field đổi; PROJECT_DELETE chỉ có {before} full snapshot (dấu vết duy nhất của hard delete); PROJECT_CREATE chỉ có {after}. <span class="ref">BR-ADM-01</span> <span class="ref">docs/07 §2.17</span></span></li><li><span class="num">9</span><span>Drawer ghép đủ 6 trụ truy vết: <b>ai</b> (actor + ip) · <b>làm gì</b> (action) · <b>với cái gì</b> (entity + deep-link) · <b>thay đổi ra sao</b> (diff) · <b>khi nào</b> (timestamp GMT+7) · <b>đối chiếu log hệ thống thế nào</b> (traceId). <span class="ref">FR-ADM-04</span></span></li></ol></div><h2 id="_3-empty-loading-error" tabindex="-1">3. Empty / Loading / Error <a class="header-anchor" href="#_3-empty-loading-error" aria-label="Permalink to &quot;3. Empty / Loading / Error&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-3"><div class="wf-col"><span class="wf-state-label">EMPTY — FILTER KHÔNG KHỚP</span><div class="wf-empty"><b>Không có log nào khớp bộ lọc</b><br><span class="wf-small">Kiểm tra: action đúng enum? khoảng ngày có chứa thời điểm xảy ra? entity id đủ prefix (auc_/pay_/usr_)?</span><div style="margin-top:10px;"><span class="wf-btn sm">Xóa bộ lọc</span></div><span class="wf-small" style="display:block;margin-top:8px;">Lưu ý: không có log ≠ không có gì xảy ra — có thể hành động thuộc hệ khác hoặc filter sai; không bao giờ &quot;tạo log bù&quot;.</span></div></div><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON</span><div class="wf-card"><div class="pad wf-col"><div class="wf-skeleton" style="height:38px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><span class="wf-small">Skeleton filter bar + 10 dòng; đang lọc lại thì giữ bảng cũ + overlay mờ (không xóa dữ liệu đang xem).</span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR — KHÔNG LOAD ĐƯỢC</span><div class="wf-error-box"><b>Không tải được audit log</b><br><span class="wf-small">Dữ liệu không mất (append-only trong DB) — thử lại; lỗi kéo dài báo kỹ thuật kèm mã truy vết.</span><br><span class="wf-trace">traceId: 90fe12bb-5d31-4c7e</span><div style="margin-top:10px;"><span class="wf-btn">Thử lại</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">10</span><span>4-state: Loading (skeleton) → Empty (hướng dẫn sửa filter + khẳng định &quot;không tạo log bù&quot;) → Error (message + traceId + Thử lại) → Data (mục 1–2). Empty của audit đặc biệt nhạy cảm — phải nói rõ không-log ≠ không-hành-động để tránh suy diễn sai khi điều tra. <span class="ref">docs/05 §1.4</span></span></li><li><span class="num">11</span><span>Xuất CSV thành công → toast ok <b>&quot;Đã xuất 4.132 dòng audit (filter hiện hành) — hành động xuất đã được ghi log&quot;</b>; quá 50k dòng → toast warn &quot;Kết quả vượt 50.000 dòng — thu hẹp khoảng ngày để xuất&quot;. <span class="ref">FR-STAT-02</span></span></li></ol></div><h2 id="_4-checklist-designer-khi-dung-figma-cho-sc-49" tabindex="-1">4. Checklist designer khi dựng Figma cho SC-49 <a class="header-anchor" href="#_4-checklist-designer-khi-dung-figma-cho-sc-49" aria-label="Permalink to &quot;4. Checklist designer khi dựng Figma cho SC-49&quot;">​</a></h2><ul><li>[ ] Note đỏ &quot;Audit log là bất biến&quot; luôn hiện đầu trang (không dismiss được) + badge VIEW-ONLY cạnh title</li><li>[ ] Filter bar đủ 7 điều kiện: actor / action (enum dropdown có search) / entity type / entity id / từ ngày / đến ngày / traceId — nút &quot;Áp dụng&quot; + &quot;Xóa lọc&quot;</li><li>[ ] Bảng 7 cột, badge màu theo nhóm action (tiền = danger/ok, extend = warn, dự án = info, system = phân biệt &quot;system&quot; in đậm); sort cố định created_at desc</li><li>[ ] Drawer chi tiết: đủ 6 trụ (ai/làm gì/với cái gì/khác biệt/khi nào/trace) + diff JSON monospace nguyên văn + deep-link entity read-only + nút duy nhất &quot;Sao chép traceId&quot;</li><li>[ ] Audit tự soi audit: frame &quot;hành động xuất CSV cũng được ghi log&quot; (AUDIT_EXPORT)</li><li>[ ] TUYỆT ĐỐI không vẽ: nút tạo/sửa/xóa, icon bút/thùng rác, menu ngữ cảnh trên dòng, bulk-select checkbox — review Figma reject nếu có</li><li>[ ] 4-state: skeleton / empty (kèm dòng &quot;không tạo log bù&quot;) / error+traceId / data</li><li>[ ] Responsive note: desktop-priority; ≤768px bảng cuộn ngang ưu tiên Thời gian + Action, drawer full-width, diff JSON scroll ngang trong khung</li><li>[ ] Không emoji icon production (🗓/🔍 là placeholder); giờ <code>dd/MM/yyyy HH:mm:ss</code> + GMT+7; UTC trong diff giữ nguyên ISO-8601</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',16)])])}const g=s(l,[["render",d]]);export{f as __pageData,g as default};
